import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_lowercases_and_preserves_ascii_letters_and_digits(self):
        self.assertEqual(slugify("Hello World 123"), "hello-world-123")

    def test_collapses_runs_of_separators(self):
        self.assertEqual(slugify("one---two___three...four"), "one-two-three-four")

    def test_strips_leading_and_trailing_separators(self):
        self.assertEqual(slugify(" !!!Hello!! "), "hello")

    def test_non_ascii_characters_are_separators(self):
        self.assertEqual(slugify("café 東京 déjà-vu"), "caf-d-j-vu")

    def test_only_separators_and_empty_input_return_empty(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify(" --_é! "), "")

    def test_ascii_boundary_characters(self):
        self.assertEqual(slugify("AZaz09"), "azaz09")


if __name__ == "__main__":
    unittest.main()
